async function readSaarFileCore(source:File,recoverOfficialEmailFromText=true,signal?:AbortSignal):Promise<SaarReadResult>{
 try{
  throwIfSyncCancelled(signal);
  if(source.size>evidenceFileLimit)return{email:'',error:'The SAAR exceeds the 100 MB file limit.',emailRecoveryAttempted:recoverOfficialEmailFromText};
  const inspected=inspectEvidenceBytes(source.name,new Uint8Array(await source.arrayBuffer()));throwIfSyncCancelled(signal);const fields=await readSaarFormFields(inspected.pdfBytes);throwIfSyncCancelled(signal);
  if(!fields.fillable)return{email:'',error:'The SAAR is not a supported fillable AcroForm or DD2875 XFA PDF.',emailRecoveryAttempted:recoverOfficialEmailFromText};
  const fieldEmail=oneLine(fields.email??'');let email=validEmail(fieldEmail)?fieldEmail:'';
  if(!email&&recoverOfficialEmailFromText)try{const extracted=await extractPdfText(inspected.pdfBytes,6,{signal,timeoutMs:15000}),{officialEmailFromText}=await import('./saar-form-utils'),textEmail=oneLine(officialEmailFromText(extracted.text)??'');if(validEmail(textEmail))email=textEmail}catch{}
  const base={email,identity:fields.identity,organization:fields.organization,requestDate:fields.requestDate,format:fields.format,pdfName:inspected.pdfName,emailRecoveryAttempted:!!email||recoverOfficialEmailFromText};
  if(!email&&!recoverOfficialEmailFromText)return base;
  return email?base:{...base,error:'The SAAR Official Email field is empty or invalid, and no valid email address was found immediately after the Official Email label in selectable PDF text.',manualEntryAllowed:true};
 }catch(error){throwIfSyncCancelled(signal);if(error instanceof OperationTimeoutError)throw error;return{email:'',error:'The SAAR is not a readable fillable PDF.',emailRecoveryAttempted:recoverOfficialEmailFromText}}
}
