async function verifyBrowserAudit(directory:FileSystemDirectoryHandle){const names:string[]=[];for await(const[name,entry]of(directory as DirectoryWithEntries).entries()){if(entry.kind!=='file'||!name.startsWith('audit-')||!name.endsWith('.jsonl'))continue;if(!/^audit-\d{4}-\d{2}-\d{2}\.jsonl$/.test(name))throw new Error('An audit-log filename is invalid.');names.push(name)}if(names.length>10000)throw new Error('The audit-log file count exceeds the verification limit.');let state:AuditChainState={entries:0,headHash:auditGenesisHash};const recent:AuditEntry[]=[];for(const name of names.sort()){const text=await withReadRetry(async operationSignal=>{throwIfSyncCancelled(operationSignal);const handle=await directory.getFileHandle(name),file=await handle.getFile();if(file.size<=0||file.size>100*1024*1024)throw new Error(`${name} is empty or exceeds the audit-log size limit.`);const value=await file.text();throwIfSyncCancelled(operationSignal);return value},{timeoutMs:30000,retryTimeoutMs:60000,message:`Audit verification could not read ${name} within 30 seconds.`,retryMessage:`Audit verification could not read ${name} after one retry within 60 seconds.`});state=await verifyAuditText(text,state,name.slice(6,16));for(const line of text.split(/\r?\n/).filter(Boolean)){recent.push(JSON.parse(line) as AuditEntry);if(recent.length>500)recent.shift()}}return{...state,files:names.length,legacyFiles:0,recent:recent.reverse()}}
async function appendAudits(actions:string[],systemId=trackerWindow().__activeSystemId){const h=rootFor(systemId),cleanActions=actions.map(oneLine).filter(Boolean);if(!h||!cleanActions.length){lastAuditError='';return true}try{if(isPortableRoot(h)){for(let offset=0;offset<cleanActions.length;offset+=10000)await portableRequest(h,'audit-batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(cleanActions.slice(offset,offset+10000))});lastAuditError='';return true}const dir=await browserSupportDirectory(h,'Audit Logs'),verified=await verifyBrowserAudit(dir);let state:AuditChainState=verified,requestedTime=Date.now();const daily=new Map<string,string[]>();for(const action of cleanActions){if(state.lastTimestamp)requestedTime=Math.max(requestedTime,Date.parse(state.lastTimestamp)+1);const entry=await buildAuditEntry(state,currentActor(),action,new Date(requestedTime).toISOString()),day=entry.timestampUtc.slice(0,10),lines=daily.get(day);if(lines)lines.push(JSON.stringify(entry));else daily.set(day,[JSON.stringify(entry)]);state={entries:entry.sequence,headHash:entry.entryHash,firstTimestamp:state.firstTimestamp??entry.timestampUtc,lastTimestamp:entry.timestampUtc};requestedTime++}for(const[day,lines]of daily){const file=await dir.getFileHandle(`audit-${day}.jsonl`,{create:true}),existing=await file.getFile(),w=await file.createWritable({keepExistingData:true});await w.write({type:'write',position:existing.size,data:`${lines.join('\n')}\n`});await w.close()}lastAuditError='';return true}catch(error){lastAuditError=oneLine(error instanceof Error?error.message:'The audit log could not be verified or extended.');console.error('Unable to write or verify audit log',error);return false}}
