  const indexHandle=await root.getFileHandle(syncIndexFilename),indexFile=await indexHandle.getFile();if(indexFile.size<=0||indexFile.size>50*1024*1024)return new Map<string,SyncIndexEntry>();
  const text=await indexFile.text(),checksumHandle=await root.getFileHandle(syncIndexChecksumFilename),checksumFile=await checksumHandle.getFile();if(checksumFile.size<=0||checksumFile.size>1024)return new Map<string,SyncIndexEntry>();
