 async function logOff(){const systemId=trackerWindow().__activeSystemId,root=rootFor(systemId);if(sessionState!=='active')return;shutdownStarted.current=true;try{if(root&&systemId){await writeSystemManifest(root,systemId,systems,users);warnAuditFailure(await appendAudit('OPERATOR LOG OFF: final backup completed and shared-folder lock released',systemId));await releaseLease(root,sessionId)}setSessionMessage(trackerWindow().__portableHost?'Logoff is complete. The final backup is verified and the application is closing.':'You are logged off. The final backup is complete and the shared-folder lock has been released.');setSessionState('logged-off');setModal(null);if(trackerWindow().__portableHost){const request=await portableFetch(fetch,'/api/logoff','operator logoff',{method:'POST',credentials:'same-origin',cache:'no-store'},false,0,10000);if(!request.ok)throw new Error('The Windows launcher did not accept the logoff request.');const ready=await portableFetch(fetch,'/api/shutdown-ready','shutdown ready',{method:'POST',credentials:'same-origin',cache:'no-store',keepalive:true},false,0,10000);if(!ready.ok)throw new Error('The Windows launcher could not confirm the final backup.')}}catch(error){const reported=await reportOperationalError('Operator logoff failed.',error,systemId);shutdownStarted.current=false;await launcherPost('/api/backup-failed',true);setSessionMessage(reported.message);setSessionState('blocked')}}
