 async function openRestore(){const systemId=effectiveSelected,root=rootFor(systemId);if(!root){alert('Map the selected information system folder before restoring a backup. Details: the backup folder is unavailable without its mapping. Audit: no mapped system audit log is available.');return}setRestoreCandidates([]);setRestoreDrill(null);setRestoreLoading(true);setModal('restore');try{if(isPortableRoot(root)){const response=await portableRequest(root,`backups?logical=${encodeURIComponent(systemId)}`);setRestoreCandidates(await response.json() as RestoreCandidate[])}else setRestoreCandidates(await listRestoreCandidates(root,systemId))}catch(error){await showOperationalError('Backup listing failed.',error,systemId,{fallback:'Unable to read the backup folder.'});setModal(null)}finally{setRestoreLoading(false)}}
