  {newUserSaarCorrections.length>0&&<><h3>New-User SAARs Requiring Correction</h3><p className="hint">These SAARs were not treated as ordinary unmatched evidence. Each failed a specific user-admission check and remains excluded from the User Directory until corrected.</p><div className="unmatched-list">{newUserSaarCorrections.map(candidate=><small key={candidate.id}>{candidate.filename} · {candidate.reason}</small>)}</div></>}
